223|const readNestedContextValue = (
224|  context: Record<string, unknown> | null | undefined,
225|  path: string,
226|): unknown => {
227|  const segments = path.split(".").map((segment) => segment.trim()).filter(Boolean);
228|  let cursor: unknown = context;
229|  for (const segment of segments) {
230|    if (cursor && typeof cursor === "object" && segment in (cursor as Record<string, unknown>)) {
231|      cursor = (cursor as Record<string, unknown>)[segment];
232|    } else {
233|      return undefined;
234|    }
235|  }
236|  return cursor;
237|};
