239|const applyResponseDataPath = (
240|  payload: unknown,
241|  responseMapping?: { dataPath?: string; arrayPath?: string },
242|): unknown => {
243|  if (!responseMapping) {
244|    return payload;
245|  }
246|  const arrayPath = responseMapping.arrayPath?.trim();
247|  if (arrayPath) {
248|    const arrayValue = readNestedContextValue(
249|      payload && typeof payload === "object" ? payload as Record<string, unknown> : {},
250|      arrayPath,
251|    );
252|    if (Array.isArray(arrayValue)) {
253|      return arrayValue;
254|    }
255|  }
256|  const dataPath = responseMapping.dataPath?.trim();
257|  if (!dataPath || !payload || typeof payload !== "object") {
258|    return payload;
259|  }
260|  return readNestedContextValue(payload as Record<string, unknown>, dataPath);
